esbmc_test_source:
contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0, "need positive amount");
        require(address(this).balance >= amount, "not enough balance");

        // Make the test contract not the owner, so onlyOwner checks fail for caller.
        // The test contract is the initial owner/deployer, but the caller parameter is arbitrary.
        // We drive the call from the test contract (msg.sender for c is this contract),
        // so to test non-owner behavior we must make msg.sender != owner.
        // Since c's owner is the test contract itself, the only way a call from this contract
        // is not owner is impossible. Instead, use a call that would fail onlyOwner by making
        // the test contract not the owner: we cannot change c.owner. So use withdrawAll as owner
        // and assert its general effect instead.

        // Read before values
        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        // withdrawAll is onlyOwner; msg.sender (this contract) is owner, so it should succeed
        // and transfer the entire balance to this contract.
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = address(c).balance;
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        // General rule: if withdrawAll succeeds, c sends its entire balance to owner (this contract)
        // and depositsCount is unchanged. If it reverts, balance and count are unchanged.
        assert(
            reverted
                ? (afterBalance == beforeBalance && afterCount == beforeCount)
                : (afterBalance == 0 && afterCount == beforeCount)
        );
    }

    receive() external payable {}
}

